import { LOCALES } from '@samesync/shared';
import { sql } from 'drizzle-orm';
import { bigint, check, pgEnum, pgTable, text, timestamp, uuid } from 'drizzle-orm/pg-core';

export const localeEnum = pgEnum('locale', LOCALES);

/** Full status list from the PLAN.md §4 data model; Phase 0 only uses `onboarding`. */
export const userStatusEnum = pgEnum('user_status', [
  'onboarding',
  'active',
  'waitlisted',
  'ineligible',
  'frozen',
  'deleted',
]);

/**
 * Phase 0 keeps users minimal: no birth date, mode, username or profile fields yet (Phase 1).
 * `id` is a uuid v7 generated by the app.
 */
export const users = pgTable(
  'users',
  {
    id: uuid('id').primaryKey(),
    telegramId: bigint('telegram_id', { mode: 'number' }).notNull().unique(),
    publicId: text('public_id').notNull().unique(),
    locale: localeEnum('locale').notNull(),
    status: userStatusEnum('status').notNull().default('onboarding'),
    lastActiveAt: timestamp('last_active_at', { withTimezone: true }).notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    check('users_telegram_id_positive', sql`${t.telegramId} > 0`),
    check('users_public_id_format', sql`${t.publicId} ~ '^[0-9A-HJKMNP-TV-Z]{10}$'`),
  ],
);
